-- Harvestly demo data (generated by make_seed.py on 2026-10-15 07:42).
-- Run as HARVESTLY in Database Actions > SQL with Run Script (F5).
-- Re-running is safe: it first removes earlier seed rows (chat ids starting 'seed-').
-- Real registrations from the Telegram bot are left alone.

DELETE FROM alerts WHERE batch_id IN (SELECT b.id FROM batches b JOIN farmers f ON f.id = b.farmer_id WHERE f.telegram_chat_id LIKE 'seed-%');
DELETE FROM batches WHERE farmer_id IN (SELECT id FROM farmers WHERE telegram_chat_id LIKE 'seed-%');
DELETE FROM farmers WHERE telegram_chat_id LIKE 'seed-%';
DELETE FROM weather_cache;
COMMIT;

-- Farmers: 160
COMMIT;

-- Batches: 234
COMMIT;

-- Alerts: 17
COMMIT;

-- Weather history (7-day trailing values, one row a day, same as scheduler.py stores)
COMMIT;

-- Check: expect the counts printed by make_seed.py
SELECT (SELECT COUNT(*) FROM farmers WHERE telegram_chat_id LIKE 'seed-%') AS seed_farmers,
       (SELECT COUNT(*) FROM batches) AS batches, (SELECT COUNT(*) FROM alerts) AS alerts,
       (SELECT COUNT(*) FROM weather_cache) AS weather_rows FROM dual;
SELECT risk_level, COUNT(*) AS batches, SUM(bags) AS bags FROM batches GROUP BY risk_level ORDER BY 1;
